//! H-1 band-code tests: corpus-sample fixture plus emitter mask tests.
//!
//! The fixture `tests/fixtures/band_code_sample.bin` was generated by
//! `crates/helion-ultrascale/tools/gen_band_code_fixture.py` (seed
//! 20261120) from the decoder-validation corpus: 205 frames (185
//! block-0, 20 block-1). Expected counts, printed by the generator:
//! MAP-A masked exact 165 of 185, H76 exact 155 of 185, Q frames 20,
//! other residuals 0, block-1 stored band always 0.

use helion_ultrascale::band_code::{
    BandFormula, compute_band, compute_band_h76, compute_band_map_a, frame_band,
};
use helion_ultrascale::bitgen::{
    FRAME_BITS, FrameWords, StubDevice, StubSegbitsDb, emit_bitstream, emit_frames, far_decode,
    parse_bitstream,
};
use helion_ultrascale::bitloc::lut_locations;
use helion_ultrascale::{BitRef, ClbTileType};
use std::path::PathBuf;

fn fixture_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("band_code_sample.bin")
}

fn read_u32(bytes: &[u8], off: &mut usize) -> u32 {
    let v = u32::from_le_bytes(bytes[*off..*off + 4].try_into().unwrap());
    *off += 4;
    v
}

fn read_u64(bytes: &[u8], off: &mut usize) -> u64 {
    let v = u64::from_le_bytes(bytes[*off..*off + 8].try_into().unwrap());
    *off += 8;
    v
}

#[test]
fn corpus_sample_reproduces_python_counts() {
    let bytes = std::fs::read(fixture_path()).unwrap();
    let mut off = 0usize;
    let n = read_u32(&bytes, &mut off) as usize;
    assert_eq!(n, 205, "fixture holds 205 frames");
    let mut b0 = 0usize;
    let mut map_a_exact = 0usize;
    let mut h76_exact = 0usize;
    let mut q = 0usize;
    let mut other = 0usize;
    let mut b1 = 0usize;
    for _ in 0..n {
        let far = read_u32(&bytes, &mut off);
        let mut words = [0u32; 93];
        for w in words.iter_mut() {
            *w = read_u32(&bytes, &mut off);
        }
        let mut mask_words = [0u32; 93];
        for w in mask_words.iter_mut() {
            *w = read_u32(&bytes, &mut off);
        }
        let stored = read_u64(&bytes, &mut off);
        assert_eq!(
            stored,
            frame_band(&words),
            "stored band matches frame words"
        );
        let mut mask = [false; FRAME_BITS];
        for wi in 0..93usize {
            for b in 0..32 {
                if (mask_words[wi] >> b) & 1 == 1 {
                    mask[wi * 32 + b] = true;
                }
            }
        }
        let (block, _, _, _) = far_decode(far);
        match block {
            0 => {
                b0 += 1;
                let pred_a = compute_band_map_a(&words, &mask);
                if pred_a == stored {
                    map_a_exact += 1;
                } else if pred_a ^ stored == 0xf0000000000f {
                    q += 1;
                } else {
                    other += 1;
                }
                if compute_band_h76(&words) == stored {
                    h76_exact += 1;
                }
                // The dispatcher agrees with MAP-A on block-0 frames.
                assert_eq!(compute_band(far, &words, &mask, BandFormula::MapA), pred_a);
            }
            1 => {
                b1 += 1;
                assert_eq!(stored, 0, "block-1 stored band is zero, FAR 0x{far:08x}");
                assert_eq!(
                    compute_band(far, &words, &mask, BandFormula::MapA),
                    0,
                    "block-1 computed band is zero, FAR 0x{far:08x}"
                );
            }
            other_block => panic!("unexpected block type {other_block} in fixture"),
        }
    }
    assert_eq!(off, bytes.len(), "fixture fully consumed");
    assert_eq!(b0, 185);
    assert_eq!(map_a_exact, 165);
    assert_eq!(h76_exact, 155);
    assert_eq!(q, 20);
    assert_eq!(other, 0, "no MAP-A residual other than w");
    assert_eq!(b1, 20);
}

fn stub_db() -> StubSegbitsDb {
    // A6LUT.INIT[63:0]: 64 refs, frame offset 12, bits 63..0 in list
    // order (MSB-first, as in bitgen_roundtrip.rs). MODE.RAM: frames
    // 9 and 10, bit 19 (the golden offsets relative to base 0x600).
    let mut lut: Vec<BitRef> = Vec::new();
    for bit in (0..64).rev() {
        lut.push(BitRef::set(12, bit));
    }
    StubSegbitsDb::new(vec![
        ("CLEM".to_string(), "A6LUT.INIT[63:0]".to_string(), lut),
        (
            "CLEM".to_string(),
            "ALUT.MODE.RAM".to_string(),
            vec![BitRef::set(9, 19), BitRef::set(10, 19)],
        ),
    ])
}

fn stub_device_y0() -> StubDevice {
    StubDevice::new(
        "xcku3p",
        Some(0x04A6_3093),
        vec![("SLICE_X0Y0".to_string(), "CLEM".to_string(), 0x600)],
        vec![0x609, 0x60a, 0x60c],
    )
}

#[test]
fn emit_masks_ram_mode_init_through_segbits_path() {
    // Y0 slice: INIT resolves through segbits. One set INIT bit at
    // absolute bit 0 of frame 0x60c (value bit 0 is the last listed
    // ref). Logic mode must carry its MAP-A column; RAM mode must
    // carry a zero band on that frame (the bit is masked).
    let db = stub_db();
    let device = stub_device_y0();
    let init = "SLICE_X0Y0.A6LUT.INIT[63:0] = 64'h0000000000000001\n";
    let logic = emit_frames(init, &device, &db).unwrap();
    let logic_band = frame_band(&logic[&0x60c]);
    let mut single = [0u32; 93];
    single[0] = 1;
    let expected = compute_band_map_a(&single, &[false; FRAME_BITS]);
    assert_eq!(expected, 0x110100011000, "column of absolute bit 0");
    assert_eq!(logic_band, expected, "logic-mode INIT bit feeds the band");
    assert_eq!(logic[&0x60c][0] & 1, 1, "the INIT bit itself is set");

    let ram_fasm = format!("{init}SLICE_X0Y0.ALUT.MODE.RAM\n");
    let ram = emit_frames(&ram_fasm, &device, &db).unwrap();
    assert_eq!(ram[&0x60c][0] & 1, 1, "the INIT bit itself is set");
    assert_eq!(
        frame_band(&ram[&0x60c]),
        0,
        "RAM-mode INIT bit is masked out of the band"
    );
}

#[test]
fn emit_masks_ram_mode_init_through_table_path() {
    // Off-Y0 slice: INIT resolves through the Y_ofst tables. INIT bit
    // 0 sits at lut_locations(CLEM, 20, A)[0]; the same mask rule must
    // hold there as on the segbits path.
    let db = stub_db();
    let device = StubDevice::new(
        "xcku3p",
        Some(0x04A6_3093),
        vec![("SLICE_X0Y20".to_string(), "CLEM".to_string(), 0x600)],
        vec![],
    );
    let loc = lut_locations(ClbTileType::Clem, 20, 0).unwrap()[0];
    let init_far = 0x600 + loc.minor;
    let mut single: FrameWords = [0u32; 93];
    single[(loc.frame_ofst / 32) as usize] |= 1u32 << (loc.frame_ofst % 32);
    let expected = compute_band_map_a(&single, &[false; FRAME_BITS]);
    assert_ne!(expected, 0, "the single INIT bit has a nonzero column");

    let init = "SLICE_X0Y20.A6LUT.INIT[63:0] = 64'h0000000000000001\n";
    let logic = emit_frames(init, &device, &db).unwrap();
    assert_eq!(
        frame_band(&logic[&init_far]),
        expected,
        "logic-mode INIT bit feeds the band (table path)"
    );
    let ram_fasm = format!("{init}SLICE_X0Y20.ALUT.MODE.RAM\n");
    let ram = emit_frames(&ram_fasm, &device, &db).unwrap();
    assert_eq!(
        frame_band(&ram[&init_far]),
        0,
        "RAM-mode INIT bit is masked out of the band (table path)"
    );
}

#[test]
fn emit_parse_roundtrip_keeps_band_bits() {
    // Emitting then parsing back a LUTRAM design must succeed: the
    // band bits are a computed code, not a feature, so parse-back
    // exempts them from the unexplained-bits check and renders the
    // same FASM lines.
    let db = stub_db();
    let device = stub_device_y0();
    let fasm = "SLICE_X0Y0.A6LUT.INIT[63:0] = 64'h0000000000000001\n\
                SLICE_X0Y0.ALUT.MODE.RAM\n";
    let bytes = emit_bitstream(fasm, &device, &db).unwrap();
    let back = parse_bitstream(&bytes, &device, &db).unwrap();
    assert!(
        back.contains("SLICE_X0Y0.A6LUT.INIT[63:0]"),
        "parse-back renders the INIT line, got:\n{back}"
    );
    assert!(
        back.contains("SLICE_X0Y0.ALUT.MODE.RAM\n"),
        "parse-back renders MODE.RAM, got:\n{back}"
    );
    // The band survives the round trip: re-emitting the parse-back
    // sets the same band on the INIT frame.
    let frames1 = emit_frames(fasm, &device, &db).unwrap();
    let frames2 = emit_frames(&back, &device, &db).unwrap();
    assert_eq!(frame_band(&frames1[&0x60c]), frame_band(&frames2[&0x60c]));
}
